test('Rotating body local contact follows real point velocity, remains off-center, and jump normal uses present angle',()=>{const s=fresh(['sticky_frogs','tilt_a_frog']);const platform=s.arenaChaos.capture()!.platforms[0],terrain=[];for(let b=s.world.getBodyList();b;b=b.getNext())if((b.getUserData()as any)?.chaosPlatform)terrain.push(b);const b=terrain.find(b=>Math.abs(b.getPosition().x-platform.x!)<.01&&Math.abs(b.getPosition().y-platform.y!)<.01)!;const f=s.frogs[0],local=Vec2(platform.solid.w*.2,-platform.solid.h/2-s.tuning.frogRadius+.01),p=b.getWorldPoint(local);f.body.setTransform(p,0);s.world.step(0);s.stickyFrogs.before();assert.ok(s.stickyFrogs.support(f)?.body===b);const anchor=capture(s).stickyFrogs!.attachments[0]!.point;assert.ok(Math.abs(anchor.x)>.1);for(let i=0;i<80;i++)s.step();assert.ok(Number.isFinite(f.body.getPosition().x));assert.ok(s.stickyFrogs.support(f),'rotating support lost adhesion');{const out=s.stickyFrogs.normal(f)!.clone();s.launch(f,0,defaults.chargeSeconds);assert.ok(Vec2.dot(f.body.getLinearVelocity(),out)>8);assert.equal(s.stickyFrogs.support(f),undefined);}assert.ok(Math.abs(b.getAngle())>.005);});
test('Gravity reversal retains adhesion and charge; Moon/Butterfeet/Wind respect adhesion without mutating baseline',()=>{for(const extra of['gravity_flip','moon_frogs','butterfeet','windy_weather']as const){const s=fresh(['sticky_frogs',extra]),{f}=face(s,Vec2(1,0));s.setInput(0,{x:0,y:0,held:true});for(let i=0;i<30;i++)s.step();assert.ok(f.charging);if(extra==='gravity_flip'){s.tick=480;s.step();assert.ok(f.charging);assert.equal(s.chaosGravityDirection,-1);}assert.ok(s.stickyFrogs.support(f));applyChaos(s,[]);assert.equal(s.stickyFrogs.capture(),undefined);assert.deepEqual(s.tuning,defaults);}});
