test('All modes retain body-contact rules at wall/ceiling; no tag immunity or collider changes',()=>{for(const mode of['poison','freeze','classic']){const s=fresh(),{f}=face(s,Vec2(1,0));const g=s.frogs[1];g.body.setActive(true);g.body.setTransform(Vec2(f.body.getPosition().x,f.body.getPosition().y+.88),0);s.world.step(0);s.world.step(0);s.stickyFrogs.before();const t={announcementTicks:0,countdownTicks:0,graceTicks:60},r=mode==='classic'?new ClassicRules([0,1],0,{...t,roundTicks:3600,pointsPerSecond:1}):mode==='freeze'?new FreezeRules([0,1],0,{...t,roundTicks:3600,protectionTicks:60,pointsPerSecond:1,freezePoints:3,clearBonus:5}):new OutbreakRules([0,1],0,t);r.advanceClock(0);assert.deepEqual(r.infect(1,frogBodyContacts(s)),[1]);assert.equal(s.tuning.frogRadius,defaults.frogRadius);}});
